import React from 'react';
import styled from 'styled-components';

const HeroSection = styled.section`
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: ${({ theme }) => theme.bg};
  color: ${({ theme }) => theme.text};
  text-align: center;
  padding: 0.5rem 1.5rem 2rem 1.5rem;
`;

const Intro = styled.h2`
  font-size: 1.2rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  color: ${({ theme }) => theme.text};
  opacity: 0.7;
  margin-bottom: 0rem;
`;

const Name = styled.h1`
  font-size: 3.2rem;
  font-weight: 900;
  letter-spacing: -2px;
  margin-bottom: 0.5rem;
  color: ${({ theme }) => theme.text};
`;

const Title = styled.h3`
  font-size: 1.5rem;
  font-weight: 700;
  color: ${({ theme }) => theme.text};
  margin-bottom: 0.5rem;
`;

const Tagline = styled.p`
  font-size: 1.15rem;
  color: ${({ theme }) => theme.text};
  opacity: 0.8;
  margin-bottom: 2.8rem;
  max-width: 520px;
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 2rem;
  margin-top: 1.5rem;
`;

const HeroButton = styled.a`
  padding: 0.85rem 2.2rem;
  border-radius: 100px;
  border: 1.5px solid ${({ theme }) => theme.text};
  background: transparent;
  color: ${({ theme }) => theme.text};
  font-size: 1.08rem;
  font-weight: 600;
  text-decoration: none;
  transition: background 0.18s, color 0.18s;
  cursor: pointer;
  &:hover, &:focus {
    background: ${({ theme }) => theme.text};
    color: ${({ theme }) => theme.bg};
  }
`;

const Hero = () => (
  <HeroSection id="hero">
    <Intro>HELLO, I'M</Intro>
    <Name>VALDRIN SHALA</Name>
    <Title>Frontend Developer & UI Builder</Title>
    <Tagline>
      Crafting modern, accessible web interfaces <br />
      with clean code, performance, and precision.
    </Tagline>
    <ButtonGroup>
      <HeroButton href="#projects">View Projects</HeroButton>
      <HeroButton href="#contact">Get In Touch</HeroButton>
    </ButtonGroup>
  </HeroSection>
);

export default Hero;
